#!/usr/bin/env node
// Generates contracts/sbtc-gas-swap-v1-simnet.clar from contracts/sbtc-gas-swap-v1.clar.
//
// Simnet cannot (a) run mainnet-format principals through `is-standard`, (b) seed
// the real pools, or (c) set tx-sponsor?. So the simnet build substitutes exactly
// the tokens listed in SUBSTITUTIONS and nothing else. `verify()` proves it: after
// reversing the substitutions the structure hash of the generated file equals the
// structure hash of the source. Run with --verify to check an existing output.
//
// Usage: node scripts/build-simnet-variant.mjs [--verify]

import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const SRC = join(here, "..", "contracts", "sbtc-gas-swap-v1.clar");
const OUT = join(here, "..", "contracts", "sbtc-gas-swap-v1-simnet.clar");

// mainnet token -> simnet token. Each mainnet token must appear in the source.
export const SUBSTITUTIONS = [
  // pools and their helpers (sbtc-token stays real: simnet ships it and can mint it)
  ["'SM1793C4R5PZ4NS4VQ4WMP7SKKYVH8JZEWSZ9HCCR.xyk-core-v-1-2", ".mock-xyk-core"],
  ["'SP20X3DC5R091J8B6YPQT638J8NR1W83KN6TN5BJY.univ2-pool-v1_0_0-0070", ".mock-velar-pool"],
  ["'SP1PFR4V08H1RAZXREBGFFQ59WB739XM8VVGTFSEA.dlmm-swap-router-v-1-1", ".mock-dlmm-router"],
  // the sponsor read: simnet always has tx-sponsor? = none
  ["tx-sponsor?", "(contract-call? .mock-sponsor get-sponsor)"],
];

const HEADER = `;; GENERATED by scripts/build-simnet-variant.mjs from sbtc-gas-swap-v1.clar. Do not edit.
;; Differences from the mainnet contract are exactly the substitutions listed in that script.
`;

export function structureHash(source) {
  // Tokenize: drop comments and all whitespace; hash the token stream. Formatting-independent.
  const noComments = source.replace(/;;[^\n]*/g, "");
  const tokens = noComments.match(/\(|\)|\{|\}|[^\s(){}]+/g) ?? [];
  // Tokens are joined with U+0001 so token boundaries stay part of the hash ("ab c" differs from "a bc").
  return createHash("sha256").update(tokens.join("\u0001")).digest("hex");
}

export function build(source) {
  let out = source;
  for (const [from, to] of SUBSTITUTIONS) {
    if (!out.includes(from)) throw new Error(`substitution source not found: ${from}`);
    out = out.split(from).join(to);
  }
  return HEADER + out;
}

export function reverse(generated) {
  let out = generated.startsWith(HEADER) ? generated.slice(HEADER.length) : generated;
  for (const [from, to] of [...SUBSTITUTIONS].reverse()) {
    out = out.split(to).join(from);
  }
  return out;
}

export function verify(source, generated) {
  const a = structureHash(source);
  const b = structureHash(reverse(generated));
  if (a !== b) throw new Error(`simnet variant drifted from source: ${a} != ${b}`);
  return a;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const source = readFileSync(SRC, "utf8");
  if (process.argv.includes("--verify")) {
    const generated = readFileSync(OUT, "utf8");
    console.log("ok structure hash", verify(source, generated));
  } else {
    const generated = build(source);
    writeFileSync(OUT, generated);
    console.log("wrote", OUT, "structure hash", verify(source, generated));
  }
}
